import{_ as a,o as t,c as s,ag as n}from"./chunks/framework.BIas3y6W.js";const u=JSON.parse('{"title":"Week 1 — Prompt starters","description":"","frontmatter":{"source":"weeks/01-hello-vibe-coding/prompt-starters.md"},"headers":[],"relativePath":"weeks/01-hello-vibe-coding/prompt-starters.md","filePath":"weeks/01-hello-vibe-coding/prompt-starters.md"}'),o={name:"weeks/01-hello-vibe-coding/prompt-starters.md"};function i(p,e,l,r,h,d){return t(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="week-1--prompt-starters" tabindex="-1">Week 1 — Prompt starters <a class="header-anchor" href="#week-1--prompt-starters" aria-label="Permalink to &quot;Week 1 — Prompt starters&quot;">​</a></h1><p>Copy a prompt, replace everything in <code>[square brackets]</code>, and send it. Every prompt uses the four parts you&#39;ll study in week 3: <strong>Goal · Context · Constraints · Done when</strong>. All of them are 🟢 AI on.</p><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>Your page will be public. Use a first name or nickname only. Never put your surname, email, phone number, address, or anything about other people into a prompt or onto the page.</p></div><h2 id="starting-prompts-pick-one" tabindex="-1">Starting prompts (pick one) <a class="header-anchor" href="#starting-prompts-pick-one" aria-label="Permalink to &quot;Starting prompts (pick one)&quot;">​</a></h2><h3 id="a-personal-home-page-recommended" tabindex="-1">A. Personal home page (recommended) <a class="header-anchor" href="#a-personal-home-page-recommended" aria-label="Permalink to &quot;A. Personal home page (recommended)&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Goal: Make a one-page personal home page about me that I will publish on the web.</span></span>
<span class="line"><span>Context: I&#39;m in a course called Building Apps with AI. I know some Python, but I&#39;m new to HTML, CSS and JavaScript. The page is for classmates and friends. About me: my name is [first name or nickname]. I&#39;m interested in [interest 1], [interest 2] and [interest 3]. Right now I&#39;m learning [something]. I like the colors [color 1] and [color 2].</span></span>
<span class="line"><span>Constraints: One single HTML file with the CSS and JavaScript inside it. No frameworks, no libraries, no external images or fonts. It must look good on a phone and on a laptop. Keep the code readable, with a short comment at the start of each section. Do not add an email address, phone number, surname or social-media links.</span></span>
<span class="line"><span>Done when: The preview shows my name as a big heading, a short &quot;About me&quot; paragraph, a list of my interests, and one button that shows a random fun fact about me, picked from a list of five, each time I click it.</span></span></code></pre></div><h3 id="b-greeting-card" tabindex="-1">B. Greeting card <a class="header-anchor" href="#b-greeting-card" aria-label="Permalink to &quot;B. Greeting card&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Goal: Make an interactive greeting card web page for [occasion, e.g. a friend&#39;s birthday].</span></span>
<span class="line"><span>Context: I&#39;m new to web development. The card is from [my first name] to [their first name or nickname]. The mood is [funny / warm / over-the-top dramatic].</span></span>
<span class="line"><span>Constraints: One single HTML file with the CSS and JavaScript inside it. No libraries, no external images or fonts; use emoji or shapes drawn with CSS instead. Works on a phone.</span></span>
<span class="line"><span>Done when: The card shows a closed &quot;envelope&quot; first; clicking it opens the card with a message and a small celebration animation; a &quot;Play again&quot; button closes it so it can be opened again.</span></span></code></pre></div><h3 id="c-my-hobby-page" tabindex="-1">C. &quot;My hobby&quot; page <a class="header-anchor" href="#c-my-hobby-page" aria-label="Permalink to &quot;C. &quot;My hobby&quot; page&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Goal: Make a one-page site about my hobby, [hobby], with my name at the top so it can be my home page.</span></span>
<span class="line"><span>Context: I&#39;m new to web development. I want to share [three things about the hobby: e.g. how I started, my favorite gear, a tip for beginners].</span></span>
<span class="line"><span>Constraints: One single HTML file with the CSS and JavaScript inside it. No libraries, no external images or fonts. Works on a phone. No personal contact details.</span></span>
<span class="line"><span>Done when: The page has a heading with my name, three sections for the three topics, and a small interactive part, such as a &quot;random tip&quot; button that shows one of five tips.</span></span></code></pre></div><h3 id="d-learning-journal" tabindex="-1">D. Learning journal <a class="header-anchor" href="#d-learning-journal" aria-label="Permalink to &quot;D. Learning journal&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Goal: Make a personal home page that doubles as a learning journal for this course.</span></span>
<span class="line"><span>Context: I&#39;m new to web development, in a 16-week course called Building Apps with AI. My name is [first name or nickname].</span></span>
<span class="line"><span>Constraints: One single HTML file with the CSS and JavaScript inside it. No libraries, no external files. Works on a phone. The journal entries are written in the HTML, not saved anywhere.</span></span>
<span class="line"><span>Done when: The page shows my name, one sentence about why I&#39;m taking the course, and a list of 15 weekly entries where only week 1 has text (&quot;Built my first web page&quot;). Clicking an entry&#39;s title shows or hides its text.</span></span></code></pre></div><h2 id="customization-prompts" tabindex="-1">Customization prompts <a class="header-anchor" href="#customization-prompts" aria-label="Permalink to &quot;Customization prompts&quot;">​</a></h2><p>Send <strong>one</strong> at a time. Check the preview against the &quot;Done when&quot; before sending the next.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Goal: Change the color scheme.</span></span>
<span class="line"><span>Context: The page you just made.</span></span>
<span class="line"><span>Constraints: Keep everything else the same. Text must stay easy to read against the background.</span></span>
<span class="line"><span>Done when: The background and headings use [color] and [color], and all text is still readable.</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Goal: Improve how the page looks on a phone.</span></span>
<span class="line"><span>Context: The page you just made.</span></span>
<span class="line"><span>Constraints: Don&#39;t change the content.</span></span>
<span class="line"><span>Done when: In a narrow window the sections stack in one column, the text is comfortable to read, and nothing sticks out sideways.</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Goal: Add a footer.</span></span>
<span class="line"><span>Context: The page you just made.</span></span>
<span class="line"><span>Constraints: Small, quiet text. No contact details.</span></span>
<span class="line"><span>Done when: The bottom of the page says &quot;Built with AI in Building Apps with AI&quot; and the current year.</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Goal: Give the page a different typeface style.</span></span>
<span class="line"><span>Context: The page you just made. I want it to feel more [playful / elegant / techy].</span></span>
<span class="line"><span>Constraints: Only use fonts that every computer already has (a &quot;font stack&quot;), no downloaded fonts.</span></span>
<span class="line"><span>Done when: Headings and text use the new style on my laptop and my phone.</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Goal: Add a gentle animation when the page loads.</span></span>
<span class="line"><span>Context: The page you just made.</span></span>
<span class="line"><span>Constraints: CSS only. Subtle, under one second. Respect people who have &quot;reduce motion&quot; turned on in their device settings.</span></span>
<span class="line"><span>Done when: The sections fade or slide in once when the page opens, and nothing moves after that.</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Goal: Add an emoji icon next to each of my interests.</span></span>
<span class="line"><span>Context: My interests are [list them].</span></span>
<span class="line"><span>Constraints: Don&#39;t change the layout. Use plain emoji characters, no images.</span></span>
<span class="line"><span>Done when: Each interest in the list starts with a fitting emoji.</span></span></code></pre></div><h2 id="understanding-prompts" tabindex="-1">Understanding prompts <a class="header-anchor" href="#understanding-prompts" aria-label="Permalink to &quot;Understanding prompts&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Goal: Help me understand the page you just made.</span></span>
<span class="line"><span>Context: I know some Python, but I&#39;m new to HTML, CSS and JavaScript. Here is my page: [paste the complete code]</span></span>
<span class="line"><span>Constraints: Don&#39;t change the code. Go section by section, top to bottom. For each section, quote its first line, label it HTML (structure), CSS (style) or JavaScript (behavior), and explain in one or two plain-English sentences what it does. Where the JavaScript works differently from Python, say how in one line.</span></span>
<span class="line"><span>Done when: I could point at any part of the page and find the code that makes it.</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Which lines of code make [the thing I see on the page]? Quote them and explain each one in a sentence. Don&#39;t change anything.</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>What would happen if I changed [this line] to [this]? Predict it, then tell me how I can check.</span></span></code></pre></div><h2 id="the-three-habits" tabindex="-1">The three habits <a class="header-anchor" href="#the-three-habits" aria-label="Permalink to &quot;The three habits&quot;">​</a></h2><p>Add these to any prompt. You practice them in week 2 (<a href="./../02-ship-your-page/lab.html">week 2 lab</a>), and use them for the rest of the course.</p><p><strong>1. Ask me questions first.</strong> Put this before the Goal, or at the end of Constraints:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Before you write any code, ask me up to 5 questions about what I want, one at a time, and wait for each answer. Then summarize my answers in 3 bullet points and wait for me to say &quot;go&quot;.</span></span></code></pre></div><p><strong>2. Show, don&#39;t describe.</strong> Attach a cropped photo of a sketch you drew, or a screenshot of your own page with the problem circled:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>The attached picture shows [a sketch of the layout I want / my page at phone size, with the problem circled]. [Follow the arrangement in the sketch. / Explain what causes the problem, then suggest the smallest fix.]</span></span></code></pre></div><p><strong>3. Say what works before asking for a change.</strong> Start the prompt with:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Before you change anything: [the parts that work, e.g. the heading, the colors, the button and my hand-made changes] all work. Keep them exactly as they are.</span></span></code></pre></div><h2 id="fixing-prompts" tabindex="-1">Fixing prompts <a class="header-anchor" href="#fixing-prompts" aria-label="Permalink to &quot;Fixing prompts&quot;">​</a></h2><p>When something goes wrong, give the AI the three facts it can&#39;t see:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Goal: Fix a problem with my page.</span></span>
<span class="line"><span>Context: After your last change, [what I did, e.g. I clicked the button]. I expected [what should happen]. Instead [what actually happened, word for word if there&#39;s a message].</span></span>
<span class="line"><span>Constraints: Change only what&#39;s needed to fix this. Tell me what you changed and why.</span></span>
<span class="line"><span>Done when: [The behavior I expected] happens, and everything else still works.</span></span></code></pre></div><p>Two failed fixes? Use the <strong>two-strikes rule</strong>: open a fresh chat and start again with your current code.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Goal: [What I want the page to do.]</span></span>
<span class="line"><span>Context: Here is my current page. [paste the complete code] I tried [what I tried] and it didn&#39;t work because [what happened].</span></span>
<span class="line"><span>Constraints: One HTML file, no libraries. Keep everything that already works.</span></span>
<span class="line"><span>Done when: [Exact, checkable result.]</span></span></code></pre></div><h2 id="prompts-that-usually-go-badly" tabindex="-1">Prompts that usually go badly <a class="header-anchor" href="#prompts-that-usually-go-badly" aria-label="Permalink to &quot;Prompts that usually go badly&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prompt</th><th>Why it goes badly</th><th>Try instead</th></tr></thead><tbody><tr><td>&quot;Make it better.&quot;</td><td>The AI guesses what &quot;better&quot; means and changes everything</td><td>Name one thing: &quot;Make the heading bigger and the background calmer.&quot;</td></tr><tr><td>&quot;Use React&quot; or &quot;Use Tailwind.&quot;</td><td>Adds tools and a build step you can&#39;t publish by uploading one file</td><td>&quot;One HTML file, no frameworks, no libraries.&quot;</td></tr><tr><td>&quot;Add a login&quot; or &quot;Add a contact form that emails me.&quot;</td><td>Needs a server; a single file can&#39;t do this safely</td><td>Leave it out. Servers come in week 9.</td></tr><tr><td>&quot;Make it look like [famous site].&quot;</td><td>Copies someone else&#39;s design and may add their images</td><td>Show your own sketch of the layout (habit 2), and describe the feel: &quot;clean, lots of white space, bold headings; my own words and colors, no copied images.&quot;</td></tr></tbody></table>`,39)])])}const g=a(o,[["render",i]]);export{u as __pageData,g as default};
